def factor_over_cyclotomic_field(j, *, verbose=True, clear_denom=True):
    """
    Factor the minimal polynomial of the first root returned by
    ``calc_rootis(j)`` over the cyclotomic field Q(zeta_j),
    where zeta_j is a primitive j-th root of unity.

    Parameters
    ----------
    j : int
        Positive integer.
    verbose : bool, optional
        Print intermediate diagnostics if True.
    clear_denom : bool, optional
        Clear denominators before coercing into the polynomial ring.

    Returns
    -------
    sage.structure.factorization.Factorization
    """

    # -----------------------------------------------------------------------
    # 1. Obtain the symbolic root expression
    # -----------------------------------------------------------------------
    root_expr = calc_rootis(j)[_sage_const_0 ].expand()
    if verbose:
        print(f"Root expansion for j = {j}:\n{root_expr}\n")

    # -----------------------------------------------------------------------
    # 2. Define the cyclotomic field  K = ℚ(ζ_j)
    # -----------------------------------------------------------------------
    K = CyclotomicField(j, names=('zeta',)); (zeta,) = K._first_ngens(1)

    # -----------------------------------------------------------------------
    # 3. Replace symbolic primitive j-th roots of unity by the field generator
    # -----------------------------------------------------------------------
    zeta_j_symbolic = e**(_sage_const_2 *pi*I/j)
    root_expr_K = root_expr.subs({zeta_j_symbolic: zeta})

    # -----------------------------------------------------------------------
    # 4. Collect genuine polynomial variables (excluding field generator 'zeta')
    # -----------------------------------------------------------------------
    vars_in_expr = [v for v in root_expr_K.variables() if v is not zeta]
    if verbose:
        print("Polynomial indeterminates:", vars_in_expr, "\n")

    # -----------------------------------------------------------------------
    # 5. Build a multivariate polynomial ring over K
    # -----------------------------------------------------------------------
    P = PolynomialRing(K, names=[str(v) for v in vars_in_expr])
    var_map = {v: P.gen(i) for i, v in enumerate(vars_in_expr)}

    # -----------------------------------------------------------------------
    # 6. Coerce the expression into that ring
    # -----------------------------------------------------------------------
    coerced = root_expr_K.subs(var_map)
    if clear_denom:
        coerced = coerced.numerator()  # drop denominators

    poly_in_K = P(coerced)

    if verbose:
        print("Polynomial in K[x₁,…]:", poly_in_K, "\n")

    # -----------------------------------------------------------------------
    # 7. Factor and return
    # -----------------------------------------------------------------------
    factors = poly_in_K.factor()
    if verbose:
        print(f"Factorisation over ℚ(ζ_{j}):\n{factors}\n")

    return factors


